            break
        grid[x][y] = val

    # DP arrays: dp_prev[i][j] is the max sum when path1 at row i, path2 at row j at the current step
    NEG_INF = -10**9
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    # Step 2 corresponds to both paths at (1,1)
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps from 3 to 2N (inclusive)
    for step in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # i is row of path1, j is row of path2
        for i in range(1, N + 1):
            j = step - i
            if j < 1 or j > N:
                continue
            y1 = step - i   # column for path1
            y2 = step - j   # column for path2
            for pi in (i, i - 1):
                if pi < 1:
                    continue
                for pj in (j, j - 1):
                    if pj < 1:
                        continue
                    prev_val = dp_prev[pi][pj]
                    if prev_val <= NEG_INF // 2:
                        continue
                    add = grid[i][y1]
                    if i != j:
                        add += grid[j][y2]
                    new_val = prev_val + add
                    if new_val > dp_cur[i][j]:
                        dp_cur[i][j] = new_val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] > NEG_INF // 2 else 0

