def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Count horizontal aisles
    h_counts = [0] * (M - 1)  # index 0 corresponds to aisle after row 1
    for x, y, p, q in chatting_pairs:
        # horizontal separation
        for r in (x, p):
            # r is in 1..M. A aisle after row r splits rows <=r and >r
            # Only relevant if r <= M-1
            if 1 <= r <= M - 1:
                # check if the other row is on the other side
                if (x <= r < p) or (p <= r < x):
                    h_counts[r - 1] += 1
        # vertical separation
    v_counts = [0] * (N - 1)
    for x, y, p, q in chatting_pairs:
        for c in (y, q):
            if 1 <= c <= N - 1:
                if (y <= c < q) or (q <= c < y):
                    v_counts[c - 1] += 1
    # pick K horizontal aisles with highest counts
    h_candidates = [(cnt, idx + 1) for idx, cnt in enumerate(h_counts)]
    h_candidates.sort(key=lambda x: (-x[0], x[1]))
    optimal_rows = [str(idx) for _, idx in h_candidates[:K]]
    # pick L vertical aisles
    v_candidates = [(cnt, idx + 1) for idx, cnt in enumerate(v_counts)]
    v_candidates.sort(key=lambda x: (-x[0], x[1]))
    optimal_cols = [str(idx) for _, idx in v_candidates[:L]]
    return (' '.join(optimal_rows), ' '.join(optimal_cols))

