    enc_to_orig = {}
    orig_to_enc = {}

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in enc_to_orig:
            if enc_to_orig[enc_char] != orig_char:
                return "Failed"
        else:
            if orig_char in orig_to_enc and orig_to_enc[orig_char] != enc_char:
                return "Failed"
            enc_to_orig[enc_char] = orig_char
            orig_to_enc[orig_char] = enc_char

    # Ensure mapping covers all uppercase letters
    if len(enc_to_orig) != 26:
        return "Failed"

    decoded_chars = []
    for ch in message:
        if ch not in enc_to_orig:
            return "Failed"
        decoded_chars.append(enc_to_orig[ch])

    return ''.join(decoded_chars)

