def largest_prime_factor(n: int) -> int:
    """Return the larger of the two distinct prime factors of `n`."""
    if n <= 1:
        return n
    # Check for factor 2 first
    if n % 2 == 0:
        return n // 2
    # Only odd divisors needed
    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2
    # If no factor found, n is prime
    return n

