def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ''
    idx_map = {c: i for i, c in enumerate(inorder)}

    def helper(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right or post_left > post_right:
            return ''
        root = postorder[post_right]
        root_idx = idx_map[root]
        left_size = root_idx - in_left
        left_pre = helper(in_left, root_idx - 1, post_left, post_left + left_size - 1)
        right_pre = helper(root_idx + 1, in_right, post_left + left_size, post_right - 1)
        return root + left_pre + right_pre

    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ""
    # Map each value to its index in the inorder traversal for O(1) lookups
    index_map = {char: i for i, char in enumerate(inorder)}

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        """Recursively build preorder string from inorder[ in_start:in_end ) and postorder[ post_start:post_end )."""
        if in_start >= in_end:
            return ""
        root = postorder[post_end - 1]
        in_index = index_map[root]
        left_size = in_index - in_start
        right_size = in_end - in_index - 1
        left_preorder = helper(in_start, in_index, post_start, post_start + left_size)
        right_preorder = helper(in_index + 1, in_end, post_start + left_size, post_end - 1)
        return root + left_preorder + right_preorder

    return helper(0, len(inorder), 0, len(postorder))

