def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. A BFS explores all
    possible transformations. The function returns the count of unique numbers that
    can be generated from the original number, including the number itself.
    """
    # Build mapping from digit to list of possible replacements
    map_to = {}
    for x, y in rules:
        map_to.setdefault(str(x), set()).add(str(y))

    start = str(n)
    visited = {int(start)}
    queue = [start]

    while queue:
        cur = queue.pop(0)
        for i, d in enumerate(cur):
            if d not in map_to:
                continue
            for rep in map_to[d]:
                new_str = cur[:i] + rep + cur[i+1:]
                new_val = int(new_str)
                if new_val not in visited:
                    visited.add(new_val)
                    queue.append(new_str)

    return len(visited)

