def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if not areas:
        return max(0, l)
    # Sort intervals by start position
    intervals = sorted((min(a, b), max(a, b)) for a, b in areas)
    cleared = 0
    cur_start, cur_end = intervals[0]
    for start, end in intervals[1:]:
        if start <= cur_end:          # Overlaps or touches the current merged interval
            cur_end = max(cur_end, end)
        else:                         # No overlap – add the previous segment and start a new one
            cleared += cur_end - cur_start
            cur_start, cur_end = start, end
    cleared += cur_end - cur_start     # Add the last merged interval
    return max(0, l - cleared)          # Remaining trees (non‑negative)

