def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit items.
    """
    # Use 0/1 knapsack DP: dp[cap] is True if capacity `cap` can be achieved.
    dp = [False] * (V + 1)
    dp[0] = True
    # Only consider the first `n` items
    for vol in volumes[:n]:
        if vol > V:
            # Item too large to fit in the box, skip it
            continue
        # Process backwards to avoid reusing an item multiple times
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True

    # Find the maximum achievable capacity <= V
    for cap in range(V, -1, -1):
        if dp[cap]:
            return V - cap  # minimum remaining space

    # If no items can be packed, the whole capacity remains free
    return V

