            break
    return V - max_used

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        limit = a[i]
        # Prefix sums of current dp
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for s in range(1, m + 1):
            prefix[s] = (prefix[s - 1] + dp[s]) % MOD
        new_dp = [0] * (m + 1)
        for s in range(m + 1):
            low = s - limit
            if low <= 0:
                new_dp[s] = prefix[s]
            else:
                new_dp[s] = (prefix[s] - prefix[low - 1]) % MOD
        dp = new_dp
    return dp[m] % MOD

