    for limit in a:
        pref = [0] * (m + 1)
        pref[0] = dp[0]
        for j in range(1, m + 1):
            pref[j] = (pref[j - 1] + dp[j]) % MOD
        ndp = [0] * (m + 1)
        for j in range(m + 1):
            if j <= limit:
                ndp[j] = pref[j] % MOD
            else:
                ndp[j] = (pref[j] - pref[j - limit - 1]) % MOD
        dp = ndp
    return dp[m] % MOD

