def hanoi_double_iterative(n: int) -> int:
    """Return the minimal number of moves needed to transfer n pairs of identical discs
    from pole A to pole C in the double‑disc Towers of Hanoi puzzle, using an iterative
    algorithm."""
    if n < 0:
        raise ValueError("n must be non‑negative")
